enum class DeliveryState { empty, storage_blocked, unconfirmed, stopped, confirmed };
struct DeliveryResult {
    DeliveryState state = DeliveryState::storage_blocked;
    bool local_saved = false;
    std::optional<study_net::Receipt> receipt;
};

enum class OutboxStatus { pending, stopped, confirmed };

struct OutboxDocument {
  std::string origin;
  study_net::MatchRecord request;
  OutboxStatus status = OutboxStatus::pending;
  std::optional<study_net::Receipt> receipt;
};

inline std::string outbox_json(const OutboxDocument& doc) {
  if (!valid_outbox(doc)) {
    throw std::invalid_argument("invalid outbox document");
  }

  // Exactly five flat fields; request/receipt are JSON payloads stored as
  // strings so the existing small flat-wire parser can reuse them directly.
  Json j = Json::object();
  j["version"] = 1;
  j["origin"] = doc.origin;
  j["request"] = record_json(doc.request).dump();
  switch (doc.status) {
    case OutboxStatus::pending:
      j["status"] = "pending";
      break;
    case OutboxStatus::stopped:
      j["status"] = "stopped";
      break;
    case OutboxStatus::confirmed:
      j["status"] = "confirmed";
      break;
    default:
      throw std::invalid_argument("invalid outbox status");
  }
  j["receipt"] = doc.receipt.has_value()
                     ? receipt_json(*doc.receipt).dump()
                     : std::string();
  return j.dump();
}

inline bool receipt_matches(const study_net::MatchRecord& request,
                            const study_net::Receipt& receipt) {
  return receipt.row > 0 && receipt.key == request.key &&
         receipt.player_a == request.player_a &&
         receipt.player_b == request.player_b;
}

inline bool valid_outbox(const OutboxDocument& doc) {
  if (doc.origin.empty()) return false;
  if (!study_net::MatchSubmission(1).prepare(doc.request)) return false;

  switch (doc.status) {
    case OutboxStatus::confirmed:
      return doc.receipt.has_value() &&
             receipt_matches(doc.request, *doc.receipt);
    case OutboxStatus::pending:
    case OutboxStatus::stopped:
      return !doc.receipt.has_value();
  }
  return false;  // unknown enum value
}

inline std::optional<OutboxDocument> parse_outbox(const std::string& body) {
  const auto j = object(body, 5);
  if (!j) return std::nullopt;

  const auto version = number(*j, "version");
  if (!version || *version != 1) return std::nullopt;

  const auto origin = text(*j, "origin");
  const auto request_payload = text(*j, "request");
  const auto status_text = text(*j, "status");
  const auto receipt_payload = text(*j, "receipt");
  if (!origin || !request_payload || !status_text || !receipt_payload) {
    return std::nullopt;
  }

  // Decode the JSON payloads before any semantic checks.
  const auto request = parse_record(*request_payload);
  if (!request) return std::nullopt;

  OutboxStatus status;
  if (*status_text == "pending") {
    status = OutboxStatus::pending;
  } else if (*status_text == "stopped") {
    status = OutboxStatus::stopped;
  } else if (*status_text == "confirmed") {
    status = OutboxStatus::confirmed;
  } else {
    return std::nullopt;  // no defaulting of unknown values
  }

  std::optional<study_net::Receipt> receipt;
  if (!receipt_payload->empty()) {
    const auto parsed = parse_receipt(*receipt_payload);
    if (!parsed) return std::nullopt;
    receipt = *parsed;
  }

  OutboxDocument doc;
  doc.origin = *origin;
  doc.request = *request;
  doc.status = status;
  doc.receipt = receipt;

  if (!valid_outbox(doc)) return std::nullopt;
  return doc;
}

enum class LocalRead { missing, ready, too_large, unavailable };
struct LocalDocument { LocalRead state = LocalRead::unavailable; std::string body; };
// Read one bounded local document without following a final-component symlink.
// Application-owned folder and cooperative writers remain caller preconditions.
inline LocalDocument read_local_document(const std::filesystem::path& path) {
    try {
        std::error_code error;
        const auto status = std::filesystem::symlink_status(path, error);
        if (error == std::errc::no_such_file_or_directory ||
            (!error && status.type() == std::filesystem::file_type::not_found))
            return {LocalRead::missing, {}};
        if (error || !std::filesystem::is_regular_file(status)) return {};
        std::ifstream stream(path, std::ios::binary);
        if (!stream) return {};
        std::array<char, kJsonBodyBytes + 1> bytes{};
        stream.read(bytes.data(), static_cast<std::streamsize>(bytes.size()));
        if (stream.bad() || (stream.fail() && !stream.eof())) return {};
        const auto count = static_cast<std::size_t>(stream.gcount());
        if (count > kJsonBodyBytes) return {LocalRead::too_large, {}};
        return {LocalRead::ready, std::string(bytes.data(), count)};
    } catch (const std::exception&) { return {}; }
}

bool prepare(const study_net::MatchRecord& request) const {
    if (load().state != OutboxLoad::missing) return false;
    return save(OutboxDocument{origin_, request, OutboxStatus::pending, {}});
}

bool save(const OutboxDocument& next) const {
    if (!available() || next.origin != origin_ || !valid_outbox(next)) return false;
    const auto current = load();
    if (current.state == OutboxLoad::blocked) return false;
    if (current.state == OutboxLoad::missing) {
        if (next.status != OutboxStatus::pending) return false;
    } else {
        const auto& old = *current.document;
        if (old.request != next.request) return false;
        if (old.status == OutboxStatus::stopped && next.status != OutboxStatus::stopped) return false;
        if (old.status == OutboxStatus::confirmed &&
            (next.status != OutboxStatus::confirmed || old.receipt->row != next.receipt->row)) return false;
    }
    try {
        const auto body = outbox_json(next) + "\n";
        return body.size() <= kJsonBodyBytes && writer_(file_.u8string(), body);
    } catch (const std::exception&) { return false; }
}

if (!document_) {
    const auto loaded = store_.load();
    if (loaded.state == OutboxLoad::missing) return {DeliveryState::empty, false, {}};
    if (loaded.state != OutboxLoad::ready || !loaded.document) return {};
    document_ = loaded.document;
    dirty_ = true; // Visible after a failed prior save is not yet a durability confirmation.
}
if (document_->status != OutboxStatus::pending) return finish();
if (!api.valid() || api.origin() != document_->origin) return {};
if (dirty_ && !flush()) return {}; // No HTTP before the durable request barrier.
study_net::MatchSubmission submission(3);
if (!submission.prepare(document_->request)) return {};

class OutboxHttp {
public:
    explicit OutboxHttp(int port) : port_(port) {}
    bool valid() const { return port_ > 0 && port_ <= 65535; }
    std::string origin() const { return valid() ? "http://127.0.0.1:" + std::to_string(port_) : ""; }
    study_net::Reply operator()(const study_net::MatchRecord& record,
                               std::chrono::milliseconds limit) const noexcept {
        return HttpSender(port_)(record, limit);
    }
private:
    int port_;
};

    const auto result = retry_submission(submission, api, now, wait, budget);
    if (result == RetryExit::confirmed) {
        document_->status = OutboxStatus::confirmed;
        document_->receipt = *submission.receipt();
    } else if (result == RetryExit::stopped) {
        document_->status = OutboxStatus::stopped;
    } else {
        return {DeliveryState::unconfirmed, true, {}};
    }
    dirty_ = true;
    return finish();
}

bool flush() {
    if (!dirty_) return true;
    if (!store_.save(*document_)) return false;
    dirty_ = false;
    return true;
}
DeliveryResult finish() {
    const bool saved = flush();
    const auto state = document_->status == OutboxStatus::confirmed
        ? DeliveryState::confirmed : DeliveryState::stopped;
    return {state, saved, document_->receipt};
}

